insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Modern','mcq','easy','Who was the first Indian to join the Indian Civil Service?','भारतीय सिविल सेवा में शामिल होने वाले पहले भारतीय कौन थे?','{"craft": "recall"}'::jsonb,'[{"id": "a", "body": "Satyendranath Tagore", "body_hi": "सत्येंद्रनाथ टैगोर", "isCorrect": true}, {"id": "b", "body": "Surendranath Banerjee", "body_hi": "सुरेंद्रनाथ बनर्जी", "isCorrect": false}, {"id": "c", "body": "Romesh Chunder Dutt", "body_hi": "रमेश चंद्र दत्त", "isCorrect": false}, {"id": "d", "body": "Aurobindo Ghose", "body_hi": "अरविंद घोष", "isCorrect": false}]'::jsonb,2,0.66,'Satyendranath Tagore, an elder brother of Rabindranath, passed the open competition in London in 1863 and joined the service in 1864, serving mostly in the Bombay Presidency. Surendranath Banerjee and Romesh Chunder Dutt qualified in 1869; Banerjee was soon dismissed and turned to politics, while Dutt rose high in the service and later wrote the Economic History of India. Aurobindo Ghose passed the written examination in 1890 but did not take up the post. Holding the examination only in London, with a low age limit, kept Indians out -- a grievance the early Congress repeatedly raised.','रवींद्रनाथ के बड़े भाई सत्येंद्रनाथ टैगोर ने 1863 में लंदन में खुली प्रतियोगिता उत्तीर्ण की और 1864 में सेवा में शामिल हुए, अधिकतर बंबई प्रेसीडेंसी में सेवा की। सुरेंद्रनाथ बनर्जी और रमेश चंद्र दत्त 1869 में उत्तीर्ण हुए; बनर्जी को जल्द ही बर्ख़ास्त कर दिया गया और वे राजनीति में आए, जबकि दत्त सेवा में ऊँचे पद तक पहुँचे और बाद में ''इकोनॉमिक हिस्ट्री ऑफ़ इंडिया'' लिखी। अरविंद घोष ने 1890 में लिखित परीक्षा उत्तीर्ण की पर पद ग्रहण नहीं किया। परीक्षा केवल लंदन में और कम आयु-सीमा के साथ होने से भारतीय बाहर रहते थे -- यह शिकायत आरंभिक कांग्रेस ने बार-बार उठाई।','l3-t3-his-satyendranath-first-ics','original_pattern_matched','NCERT Class XII, Themes in Indian History III; NCERT (old), Modern India.','draft'),
('upsc','History','Modern','statement_based','easy','Consider the following statements about Ayyankali:','अय्यंकाली के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["He defied caste rules in Travancore by riding a bullock cart along roads that Dalits were barred from using.", "He led a strike of agricultural labourers to win the admission of Dalit children to schools."], "statements_hi": ["उन्होंने त्रावणकोर में उन सड़कों पर बैलगाड़ी चलाकर जाति-नियमों की अवहेलना की जिन पर दलितों का चलना वर्जित था।", "उन्होंने दलित बच्चों को विद्यालयों में प्रवेश दिलाने के लिए खेतिहर मज़दूरों की हड़ताल का नेतृत्व किया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. Ayyankali, born into the Pulaya community, made his ''villuvandi'' (bullock-cart) journey in 1893 to assert the right to use public roads, founded the Sadhu Jana Paripalana Sangham in 1907, and organised what is often called the first strike of farm labourers in Kerala, refusing to work the fields until Pulaya children were admitted to schools. He later sat in the Sree Moolam Popular Assembly of Travancore. His campaigns ran alongside those of Sree Narayana Guru and prepared the ground for the temple-entry and civil-rights struggles of the 1920s and 1930s.','दोनों कथन सही हैं। पुलया समुदाय में जन्मे अय्यंकाली ने सार्वजनिक सड़कों के उपयोग का अधिकार जताने के लिए 1893 में अपनी ''विल्लुवंडी'' (बैलगाड़ी) यात्रा की, 1907 में साधु जन परिपालन संघम की स्थापना की, और उस हड़ताल का आयोजन किया जिसे प्रायः केरल में खेतिहर मज़दूरों की पहली हड़ताल कहा जाता है, जिसमें पुलया बच्चों को विद्यालयों में प्रवेश मिलने तक खेतों में काम करने से इनकार किया गया। बाद में वे त्रावणकोर की श्री मूलम लोकप्रिय सभा के सदस्य बने। उनके अभियान श्री नारायण गुरु के अभियानों के साथ चले और 1920 और 1930 के दशकों के मंदिर-प्रवेश और नागरिक-अधिकार संघर्षों की भूमि तैयार की।','l3-t3-his-ayyankali','original_pattern_matched','NCERT Class XII, Themes in Indian History III; NCERT (old), Modern India.','draft'),
('upsc','History','Modern','statement_based','hard','Consider the following statements about anti-British activity abroad during the First World War:','प्रथम विश्व युद्ध के दौरान विदेश में ब्रिटिश-विरोधी गतिविधि के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The ''Silk Letter'' movement was organised by leaders linked to Deoband, including Maulana Mahmud Hasan and Ubaidullah Sindhi, to win Afghan and Ottoman support for a rising against British rule.", "A Provisional Government of India was proclaimed in Kabul in 1915, with Raja Mahendra Pratap as its President.", "Maulana Mahmud Hasan was arrested in the Hejaz and interned by the British in Malta."], "statements_hi": ["''रेशमी रूमाल'' आंदोलन देवबंद से जुड़े नेताओं, जिनमें मौलाना महमूद हसन और उबैदुल्लाह सिंधी शामिल थे, ने ब्रिटिश शासन के विरुद्ध विद्रोह के लिए अफ़ग़ान और उस्मानी समर्थन पाने हेतु संगठित किया।", "1915 में काबुल में भारत की एक अस्थायी सरकार घोषित की गई, जिसके राष्ट्रपति राजा महेंद्र प्रताप थे।", "मौलाना महमूद हसन को हिजाज़ में गिरफ़्तार कर अंग्रेज़ों ने माल्टा में नज़रबंद किया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The movement takes its name from letters written on silk cloth that Ubaidullah Sindhi sent from Kabul in 1916 and that fell into British hands, exposing the plan. In Kabul, Mahendra Pratap, Maulana Barkatullah (as prime minister) and Ubaidullah set up a government in exile in December 1915 and sought German and Afghan help, though the Amir stayed neutral. Mahmud Hasan, ''Shaikh-ul-Hind'', was handed over to the British in Mecca and held in Malta until 1920; on his return he backed the Khilafat and non-cooperation movements. The episode shows Pan-Islamic and revolutionary currents working together, alongside the Ghadarites.','तीनों कथन सही हैं। आंदोलन का नाम उन रेशमी कपड़े पर लिखे पत्रों से पड़ा जिन्हें उबैदुल्लाह सिंधी ने 1916 में काबुल से भेजा और जो अंग्रेज़ों के हाथ लग गए, जिससे योजना उजागर हो गई। काबुल में महेंद्र प्रताप, मौलाना बरकतुल्लाह (प्रधानमंत्री के रूप में) और उबैदुल्लाह ने दिसंबर 1915 में निर्वासित सरकार बनाई और जर्मन तथा अफ़ग़ान सहायता चाही, यद्यपि अमीर तटस्थ रहा। ''शेख़-उल-हिंद'' महमूद हसन को मक्का में अंग्रेज़ों को सौंप दिया गया और 1920 तक माल्टा में रखा गया; लौटने पर उन्होंने ख़िलाफ़त और असहयोग आंदोलनों का समर्थन किया। यह प्रसंग दिखाता है कि अखिल-इस्लामी और क्रांतिकारी धाराएँ ग़दरवादियों के साथ मिलकर काम कर रही थीं।','l3-t3-his-silk-letter-kabul-government','original_pattern_matched','NCERT Class XII, Themes in Indian History III; NCERT (old), Modern India.','draft'),
('upsc','History','Modern','mcq','medium','India House in London, a centre of Indian revolutionaries in the first decade of the twentieth century, was founded by:','लंदन का इंडिया हाउस, बीसवीं शताब्दी के पहले दशक में भारतीय क्रांतिकारियों का केंद्र, किसने स्थापित किया?','{"craft": "recall"}'::jsonb,'[{"id": "a", "body": "Madame Bhikaiji Rustom Cama", "body_hi": "मैडम भीकाजी रुस्तम कामा", "isCorrect": false}, {"id": "b", "body": "Lala Har Dayal", "body_hi": "लाला हरदयाल", "isCorrect": false}, {"id": "c", "body": "Madan Lal Dhingra", "body_hi": "मदन लाल ढींगरा", "isCorrect": false}, {"id": "d", "body": "Shyamji Krishna Varma", "body_hi": "श्यामजी कृष्ण वर्मा", "isCorrect": true}]'::jsonb,2,0.66,'Shyamji Krishna Varma, a Sanskrit scholar from Kutch, opened India House in Highgate in 1905 as a hostel for Indian students, with the Indian Home Rule Society and his journal The Indian Sociologist. It became a meeting place for young radicals: V.D. Savarkar lived there, and Madan Lal Dhingra, who shot Curzon Wyllie in London in 1909, was linked to it. After that killing, Krishna Varma moved to Paris and the house closed. Madame Cama, who unfurled an Indian flag at the Socialist Congress in Stuttgart in 1907, worked from Paris, and Lala Har Dayal later founded the Ghadar Party in America.','कच्छ के संस्कृत विद्वान श्यामजी कृष्ण वर्मा ने 1905 में हाईगेट में भारतीय विद्यार्थियों के छात्रावास के रूप में इंडिया हाउस खोला, जिसके साथ इंडियन होम रूल सोसाइटी और उनकी पत्रिका ''द इंडियन सोशियोलॉजिस्ट'' थी। यह युवा क्रांतिकारियों के मिलने का स्थान बना: वी.डी. सावरकर वहाँ रहे, और 1909 में लंदन में कर्ज़न वायली को गोली मारने वाले मदन लाल ढींगरा इससे जुड़े थे। उस हत्या के बाद कृष्ण वर्मा पेरिस चले गए और भवन बंद हो गया। 1907 में स्टटगार्ट के समाजवादी सम्मेलन में भारतीय ध्वज फहराने वाली मैडम कामा पेरिस से काम करती थीं, और लाला हरदयाल ने बाद में अमेरिका में ग़दर पार्टी बनाई।','l3-t3-his-india-house-krishna-varma','original_pattern_matched','NCERT Class XII, Themes in Indian History III; NCERT (old), Modern India.','draft'),
('upsc','History','Modern','statement_based','medium','Consider the following statements about the Tana Bhagat movement:','ताना भगत आंदोलन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It began among the Oraons of Chotanagpur around 1914.", "Its followers kept away from the Gandhian movement and refused to have anything to do with the Congress.", "It was led by Birsa Munda."], "statements_hi": ["यह लगभग 1914 में छोटानागपुर के उराँवों में शुरू हुआ।", "इसके अनुयायी गांधीवादी आंदोलन से दूर रहे और कांग्रेस से कोई संबंध रखने से इनकार किया।", "इसका नेतृत्व बिरसा मुंडा ने किया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Begun by Jatra Bhagat, the movement asked Oraons to give up liquor, meat, animal sacrifice and belief in spirits, and to stop working as labourers for landlords and the government; it blended religious reform with resistance to exploitation. Statement 2 is wrong: from 1921 many Tana Bhagats joined the Congress, wore khadi and the Gandhi cap and refused to pay taxes, and some lost their lands for it -- an example of how tribal movements fed into the national movement. Statement 3 is wrong: Birsa Munda led the Munda ulgulan of the 1890s, and died in 1900.','केवल कथन 1 सही है। जतरा भगत द्वारा शुरू किए गए आंदोलन ने उराँवों से शराब, मांस, पशु-बलि और भूत-प्रेत में विश्वास छोड़ने, और ज़मींदारों तथा सरकार के लिए मज़दूरी बंद करने को कहा; इसने धार्मिक सुधार को शोषण के प्रतिरोध से जोड़ा। कथन 2 ग़लत है: 1921 से अनेक ताना भगत कांग्रेस में शामिल हुए, खादी और गांधी टोपी पहनी और कर चुकाने से इनकार किया, और कुछ ने इसके लिए अपनी ज़मीनें खोईं -- यह इसका उदाहरण है कि जनजातीय आंदोलन राष्ट्रीय आंदोलन में कैसे मिले। कथन 3 ग़लत है: बिरसा मुंडा ने 1890 के दशक के मुंडा उलगुलान का नेतृत्व किया, और 1900 में उनकी मृत्यु हो गई।','l3-t3-his-tana-bhagat','original_pattern_matched','NCERT Class XII, Themes in Indian History III; NCERT (old), Modern India.','draft'),
('upsc','History','Modern','statement_based','medium','Consider the following statements about nineteenth-century reform associations:','उन्नीसवीं शताब्दी के सुधार संगठनों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Tattvabodhini Sabha, founded by Debendranath Tagore in 1839, later merged with the Brahmo Samaj.", "The Rahnumai Mazdayasnan Sabha, founded in 1851, worked for religious and social reform among the Parsis, with Dadabhai Naoroji among its founders.", "The Rahnumai Mazdayasnan Sabha was set up to defend orthodox Parsi practices against the reformers."], "statements_hi": ["1839 में देवेंद्रनाथ टैगोर द्वारा स्थापित तत्त्वबोधिनी सभा का बाद में ब्रह्म समाज में विलय हो गया।", "1851 में स्थापित रहनुमाई मज़्दयस्नान सभा ने पारसियों में धार्मिक और सामाजिक सुधार के लिए काम किया, और दादाभाई नौरोजी इसके संस्थापकों में थे।", "रहनुमाई मज़्दयस्नान सभा सुधारकों के विरुद्ध रूढ़िवादी पारसी प्रथाओं की रक्षा के लिए बनाई गई थी।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The Tattvabodhini Sabha spread Rammohun Roy''s ideas through its journal, the Tattvabodhini Patrika, edited by Akshay Kumar Datta, and its members revived the Brahmo Samaj, into which it was absorbed in 1859. The Rahnumai Mazdayasnan Sabha (''Religious Reform Association''), whose founders included Naoroji, Naoroji Furdonji and K.R. Cama, campaigned through its paper Rast Goftar for simpler rituals and for women''s education. Statement 3 reverses its purpose: it was a reforming body, not a defender of orthodoxy.','कथन 1 और 2 सही हैं। तत्त्वबोधिनी सभा ने अक्षय कुमार दत्त द्वारा संपादित अपनी पत्रिका ''तत्त्वबोधिनी पत्रिका'' के माध्यम से राममोहन राय के विचार फैलाए, और इसके सदस्यों ने ब्रह्म समाज को पुनर्जीवित किया, जिसमें 1859 में इसका विलय हो गया। रहनुमाई मज़्दयस्नान सभा (''धार्मिक सुधार संघ''), जिसके संस्थापकों में नौरोजी, नौरोजी फ़र्दुनजी और के.आर. कामा थे, ने अपने पत्र ''रास्त गोफ़्तार'' के माध्यम से सरल अनुष्ठानों और स्त्री-शिक्षा के लिए अभियान चलाया। कथन 3 इसके उद्देश्य को उलट देता है: यह सुधारवादी संस्था थी, रूढ़िवाद की रक्षक नहीं।','l3-t3-his-tattvabodhini-rahnumai','original_pattern_matched','NCERT Class XII, Themes in Indian History III; NCERT (old), Modern India.','draft'),
('upsc','History','Ancient','mcq','easy','Sopara, an ancient port where fragments of Ashoka''s major rock edicts have been found, lies near which present-day city?','सोपारा, एक प्राचीन बंदरगाह जहाँ अशोक के मुख्य शिलालेखों के अंश मिले हैं, किस वर्तमान नगर के पास है?','{"craft": "recall"}'::jsonb,'[{"id": "a", "body": "Mumbai", "body_hi": "मुंबई", "isCorrect": true}, {"id": "b", "body": "Chennai", "body_hi": "चेन्नई", "isCorrect": false}, {"id": "c", "body": "Kolkata", "body_hi": "कोलकाता", "isCorrect": false}, {"id": "d", "body": "Kochi", "body_hi": "कोच्चि", "isCorrect": false}]'::jsonb,2,0.66,'Sopara (Nala Sopara), in Palghar district north of Mumbai, is the Shurparaka of early texts, a port that traded across the Arabian Sea and was the chief town of the Aparanta region of the western coast. Pieces of Ashoka''s eighth and ninth major rock edicts were found there, and in 1882 the excavation of its stupa yielded relic caskets with small images -- evidence that the Mauryan state and Buddhism both reached the western seaboard.','सोपारा (नालासोपारा), मुंबई के उत्तर में पालघर ज़िले में, प्रारंभिक ग्रंथों का शूर्पारक है, एक बंदरगाह जो अरब सागर के पार व्यापार करता था और पश्चिमी तट के अपरांत क्षेत्र का मुख्य नगर था। वहाँ अशोक के आठवें और नौवें मुख्य शिलालेखों के अंश मिले, और 1882 में इसके स्तूप के उत्खनन से छोटी मूर्तियों वाली अवशेष-मंजूषाएँ मिलीं -- यह प्रमाण कि मौर्य राज्य और बौद्ध धर्म दोनों पश्चिमी समुद्र-तट तक पहुँचे।','l3-t3-his-sopara-shurparaka','original_pattern_matched','Archaeological Survey of India; NCERT Class XII, Themes in Indian History I.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements about Jivaka, as described in early Buddhist texts:','प्रारंभिक बौद्ध ग्रंथों में वर्णित जीवक के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["He was a physician at the court of Bimbisara, king of Magadha, and is said to have treated the Buddha.", "He is said to have learnt medicine at Taxila."], "statements_hi": ["वे मगध के राजा बिंबिसार के दरबार में चिकित्सक थे, और कहा जाता है कि उन्होंने बुद्ध का उपचार किया।", "कहा जाता है कि उन्होंने तक्षशिला में चिकित्सा सीखी।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. The Pali texts describe Jivaka Komarabhacca as a foundling raised at the Magadhan court who studied medicine for seven years at Taxila, then served Bimbisara and his son Ajatashatru and attended to the Buddha and the Sangha; he is also said to have given the Sangha a mango grove at Rajagriha. The stories show Taxila''s fame as a centre of learning well before the Mauryas, and the close links between the early Sangha and the rulers of Magadha.','दोनों कथन सही हैं। पालि ग्रंथ जीवक कोमारभच्च को मगध के दरबार में पले एक अनाथ के रूप में वर्णित करते हैं जिन्होंने तक्षशिला में सात वर्ष चिकित्सा पढ़ी, फिर बिंबिसार और उनके पुत्र अजातशत्रु की सेवा की और बुद्ध तथा संघ की चिकित्सा की; कहा जाता है कि उन्होंने राजगृह में संघ को आम का एक बाग़ भी दिया। ये कथाएँ मौर्यों से बहुत पहले शिक्षा-केंद्र के रूप में तक्षशिला की प्रसिद्धि और प्रारंभिक संघ तथा मगध के शासकों के निकट संबंधों को दिखाती हैं।','l3-t3-his-jivaka-physician','original_pattern_matched','NCERT Class XII, Themes in Indian History I.','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements about Pingala and his work:','पिंगल और उनकी कृति के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Pingala''s Chhandahsutra, a work on Sanskrit prosody, analyses metres as patterns of short and long syllables, in a way that resembles a binary system.", "A later commentary on Pingala describes the ''meru prastara'', an arrangement of numbers that corresponds to what is now called Pascal''s triangle.", "Pingala was a poet at the court of Harshavardhana."], "statements_hi": ["संस्कृत छंदःशास्त्र पर पिंगल का छंदःसूत्र छंदों को लघु और गुरु अक्षरों के प्रतिरूपों के रूप में विश्लेषित करता है, उस ढंग से जो द्विआधारी पद्धति से मिलता-जुलता है।", "पिंगल पर एक बाद की टीका ''मेरु प्रस्तार'' का वर्णन करती है, संख्याओं की एक व्यवस्था जो आज पास्कल के त्रिभुज कहे जाने वाले रूप से मेल खाती है।", "पिंगल हर्षवर्धन के दरबार में कवि थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Pingala, usually placed in the last centuries BCE, treated each metre as a sequence of laghu (short) and guru (long) syllables and gave rules for listing all possible sequences of a given length -- in effect counting with two symbols. Halayudha''s commentary in the tenth century set out the ''meru prastara'', the triangle of numbers that gives the count of combinations, centuries before Pascal. Statement 3 is wrong: Pingala lived many centuries before Harsha (seventh century CE), whose court poet was Banabhatta. The example shows how mathematics grew out of the study of language and ritual in early India.','कथन 1 और 2 सही हैं। सामान्यतः ईसा पूर्व की अंतिम शताब्दियों में रखे जाने वाले पिंगल ने हर छंद को लघु और गुरु अक्षरों के अनुक्रम के रूप में देखा और किसी दी गई लंबाई के सभी संभव अनुक्रमों को सूचीबद्ध करने के नियम दिए -- वस्तुतः दो प्रतीकों से गणना। दसवीं शताब्दी में हलायुध की टीका ने ''मेरु प्रस्तार'' प्रस्तुत किया, संख्याओं का वह त्रिभुज जो संयोजनों की संख्या देता है, पास्कल से सदियों पहले। कथन 3 ग़लत है: पिंगल हर्ष (सातवीं शताब्दी ई.) से कई शताब्दी पहले हुए, जिनके दरबारी कवि बाणभट्ट थे। यह उदाहरण दिखाता है कि प्रारंभिक भारत में गणित भाषा और अनुष्ठान के अध्ययन से कैसे विकसित हुआ।','l3-t3-his-pingala-meru-prastara','original_pattern_matched','NCERT Class XII, Themes in Indian History I; NCERT Class XI, Mathematics (Permutations and Combinations: historical note).','draft'),
('upsc','History','Ancient','mcq','medium','The Jetavana monastery, which the merchant Anathapindika is said to have bought for the Buddha by covering the ground with gold coins, was at:','जेतवन विहार, जिसे व्यापारी अनाथपिंडिक ने कथित रूप से ज़मीन को सोने के सिक्कों से ढककर बुद्ध के लिए ख़रीदा था, कहाँ था?','{"craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Vaishali", "body_hi": "वैशाली", "isCorrect": false}, {"id": "b", "body": "Sravasti", "body_hi": "श्रावस्ती", "isCorrect": true}, {"id": "c", "body": "Rajagriha (Rajgir)", "body_hi": "राजगृह (राजगीर)", "isCorrect": false}, {"id": "d", "body": "Kushinagara", "body_hi": "कुशीनगर", "isCorrect": false}]'::jsonb,2,0.66,'Jetavana lay at Sravasti, capital of the kingdom of Kosala, where the Buddha is said to have spent more rainy seasons than anywhere else and to have performed the ''twin miracle''. The scene of Anathapindika''s servants laying coins over Prince Jeta''s park is carved on the railing at Bharhut. Sravasti''s importance reflects the support the Buddha drew from rich merchants and from the kings of Kosala and Magadha; Vaishali was the Vajji capital, Rajagriha the early Magadhan capital, and Kushinagara the place of his death.','जेतवन कोसल राज्य की राजधानी श्रावस्ती में था, जहाँ कहा जाता है कि बुद्ध ने किसी भी अन्य स्थान से अधिक वर्षावास बिताए और ''यमक प्रातिहार्य'' किया। अनाथपिंडिक के सेवकों द्वारा राजकुमार जेत के उद्यान पर सिक्के बिछाने का दृश्य भरहुत की वेदिका पर उत्कीर्ण है। श्रावस्ती का महत्त्व उस समर्थन को दिखाता है जो बुद्ध को धनी व्यापारियों और कोसल तथा मगध के राजाओं से मिला; वैशाली वज्जि की राजधानी थी, राजगृह आरंभिक मगध की राजधानी, और कुशीनगर उनके महापरिनिर्वाण का स्थान।','l3-t3-his-sravasti-jetavana','original_pattern_matched','NCERT Class XII, Themes in Indian History I; Archaeological Survey of India.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about hero stones:','वीर-शिलाओं (हीरो स्टोन) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["They were set up only for kings who died in battle.", "They are found only in Tamil Nadu."], "statements_hi": ["ये केवल युद्ध में मारे गए राजाओं के लिए स्थापित की जाती थीं।", "ये केवल तमिलनाडु में पाई जाती हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2,0.66,'Neither statement is correct. Hero stones -- nadukal in Tamil, viragal in Kannada -- commemorate ordinary warriors and villagers who died in battle, in cattle raids, defending the village or fighting wild animals; related memorials honour women who committed sati. Sangam poems already speak of them, and inscribed hero stones in Tamil-Brahmi date from early centuries. They are found across peninsular and western India -- thousands in Karnataka, as well as in Andhra Pradesh, Maharashtra, Goa, Gujarat (paliyas) and Rajasthan (devlis) -- and are a valuable source for the social history of the countryside, which royal inscriptions rarely record.','कोई भी कथन सही नहीं है। वीर-शिलाएँ -- तमिल में नडुकल, कन्नड़ में वीरगल -- उन साधारण योद्धाओं और ग्रामीणों की स्मृति में हैं जो युद्ध में, पशु-छापों में, गाँव की रक्षा करते हुए या जंगली जानवरों से लड़ते हुए मारे गए; इनसे जुड़े स्मारक सती हुई महिलाओं का सम्मान करते हैं। संगम कविताएँ पहले से इनकी बात करती हैं, और तमिल-ब्राह्मी में अभिलिखित वीर-शिलाएँ आरंभिक शताब्दियों की हैं। ये प्रायद्वीपीय और पश्चिमी भारत भर में मिलती हैं -- कर्नाटक में हज़ारों, और आंध्र प्रदेश, महाराष्ट्र, गोवा, गुजरात (पालिया) और राजस्थान (देवली) में भी -- और ग्रामीण क्षेत्रों के सामाजिक इतिहास का मूल्यवान स्रोत हैं, जिसे राजकीय अभिलेख शायद ही दर्ज करते हैं।','l3-t3-his-hero-stones','original_pattern_matched','NCERT Class XII, Themes in Indian History I; Archaeological Survey of India.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about Kankali Tila at Mathura:','मथुरा के कंकाली टीला के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Excavations there uncovered the remains of a Jain stupa and many Jain images of the Kushan period.", "Its inscriptions record gifts made only by kings and queens.", "The sculptures of the Mathura school were carved mainly from white marble."], "statements_hi": ["वहाँ के उत्खननों में एक जैन स्तूप के अवशेष और कुषाण काल की अनेक जैन मूर्तियाँ मिलीं।", "इसके अभिलेख केवल राजाओं और रानियों द्वारा दिए गए दानों को दर्ज करते हैं।", "मथुरा शैली की मूर्तियाँ मुख्यतः सफ़ेद संगमरमर से गढ़ी गई थीं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Kankali Tila, dug in the late nineteenth century, yielded seated and standing tirthankaras, carved tablets of homage (ayagapatas) and railings, showing that Mathura was a major Jain centre under the Kushans as well as a Buddhist and Brahmanical one. Statement 2 is wrong: its inscriptions record gifts by merchants, artisans such as ironsmiths and perfumers, and many women, which makes them a rich source for urban society. Statement 3 is wrong: Mathura''s sculptors used the local spotted red sandstone; white marble is associated with Amaravati.','केवल कथन 1 सही है। उन्नीसवीं शताब्दी के अंत में खोदे गए कंकाली टीला से बैठे और खड़े तीर्थंकर, उत्कीर्ण पूजा-पट्ट (आयागपट्ट) और वेदिकाएँ मिलीं, जो दिखाती हैं कि कुषाणों के अधीन मथुरा बौद्ध और ब्राह्मणीय केंद्र के साथ एक प्रमुख जैन केंद्र भी था। कथन 2 ग़लत है: इसके अभिलेख व्यापारियों, लोहारों और गंधियों जैसे कारीगरों, और अनेक महिलाओं के दान दर्ज करते हैं, जो उन्हें नगरीय समाज का समृद्ध स्रोत बनाता है। कथन 3 ग़लत है: मथुरा के मूर्तिकारों ने स्थानीय चित्तीदार लाल बलुआ पत्थर का उपयोग किया; सफ़ेद संगमरमर अमरावती से जुड़ा है।','l3-t3-his-kankali-tila-mathura','original_pattern_matched','NCERT Class XII, Themes in Indian History I; NCERT Class XI, An Introduction to Indian Art.','draft'),
('upsc','History','Medieval','mcq','medium','The Kunjali Marakkars, who fought the Portuguese at sea in the sixteenth century, were the naval commanders of:','सोलहवीं शताब्दी में समुद्र में पुर्तगालियों से लड़ने वाले कुंजाली मरक्कार किसके नौसैनिक सेनापति थे?','{"craft": "recall"}'::jsonb,'[{"id": "a", "body": "the Adil Shahi Sultan of Bijapur", "body_hi": "बीजापुर के आदिलशाही सुल्तान", "isCorrect": false}, {"id": "b", "body": "the emperor of Vijayanagara", "body_hi": "विजयनगर के सम्राट", "isCorrect": false}, {"id": "c", "body": "the Mughal emperor Akbar", "body_hi": "मुग़ल सम्राट अकबर", "isCorrect": false}, {"id": "d", "body": "the Zamorin of Calicut", "body_hi": "कालीकट के ज़मोरिन", "isCorrect": true}]'::jsonb,2,0.66,'The Marakkars, a Muslim seafaring community of the Malabar coast, commanded the Zamorin''s fleet for most of the sixteenth century, harrying Portuguese shipping with fast, light vessels and resisting the Portuguese attempt to control the spice trade through passes (cartazes). The fourth Kunjali grew so powerful that the Zamorin joined the Portuguese against him; he surrendered in 1600 and was executed in Goa. The Indian Navy remembers them in the name of INS Kunjali.','मालाबार तट के मुस्लिम समुद्री समुदाय मरक्कारों ने सोलहवीं शताब्दी के अधिकांश समय ज़मोरिन के बेड़े का नेतृत्व किया, तेज़, हल्के जहाज़ों से पुर्तगाली जहाज़रानी को परेशान किया और अनुमति-पत्रों (कार्टाज़) के माध्यम से मसाला व्यापार नियंत्रित करने के पुर्तगाली प्रयास का विरोध किया। चौथा कुंजाली इतना शक्तिशाली हो गया कि ज़मोरिन ने उसके विरुद्ध पुर्तगालियों का साथ दिया; उसने 1600 में आत्मसमर्पण किया और गोवा में उसे मृत्युदंड दिया गया। भारतीय नौसेना INS कुंजाली के नाम में उन्हें याद करती है।','l3-t3-his-kunjali-marakkars','original_pattern_matched','NCERT Class VII, Our Pasts II; NCERT Class XII, Themes in Indian History II.','draft'),
('upsc','History','Medieval','statement_based','medium','Consider the following statements about the Yadavas of Devagiri:','देवगिरि के यादवों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Hemadri, a minister of the Yadava kings, gave his name to the ''Hemadpanti'' style of temple building in mortarless stone.", "Alauddin Khalji''s raid on Devagiri in 1296, before he became Sultan, brought him great wealth.", "Devagiri was the capital of the Kakatiyas."], "statements_hi": ["यादव राजाओं के मंत्री हेमाद्रि के नाम पर बिना गारे के पत्थर से मंदिर-निर्माण की ''हेमाडपंती'' शैली का नाम पड़ा।", "सुल्तान बनने से पहले 1296 में अलाउद्दीन ख़लजी के देवगिरि पर छापे से उसे भारी धन मिला।", "देवगिरि काकतीयों की राजधानी थी।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Hemadri served Mahadeva and Ramachandra in the thirteenth century and compiled the encyclopaedic Chaturvarga-chintamani; the temples named after him, built of dark basalt blocks fitted without mortar, are found across Maharashtra. Alauddin, then governor of Kara, struck Devagiri in 1296 and carried off a vast treasure that helped him seize the throne at Delhi soon after; Devagiri was later annexed and, as Daulatabad, briefly became Muhammad bin Tughlaq''s second capital. Statement 3 is wrong: the Kakatiyas ruled from Warangal.','कथन 1 और 2 सही हैं। हेमाद्रि ने तेरहवीं शताब्दी में महादेव और रामचंद्र की सेवा की और विश्वकोशीय ''चतुर्वर्ग-चिंतामणि'' संकलित की; उनके नाम वाले मंदिर, जो बिना गारे के जोड़े गए गहरे बेसाल्ट खंडों से बने हैं, पूरे महाराष्ट्र में मिलते हैं। तब कड़ा के सूबेदार अलाउद्दीन ने 1296 में देवगिरि पर धावा बोला और विशाल ख़ज़ाना ले गया जिसने जल्द ही दिल्ली का सिंहासन हथियाने में उसकी मदद की; देवगिरि को बाद में मिला लिया गया और दौलताबाद के रूप में यह थोड़े समय के लिए मुहम्मद बिन तुग़लक़ की दूसरी राजधानी बना। कथन 3 ग़लत है: काकतीय वारंगल से शासन करते थे।','l3-t3-his-yadavas-hemadri-devagiri','original_pattern_matched','NCERT Class VII, Our Pasts II; Archaeological Survey of India.','draft'),
('upsc','History','Medieval','match_the_following','medium','Consider the following pairs of Vijayanagara dynasties and rulers who belonged to them:','विजयनगर के राजवंशों और उनसे संबंधित शासकों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Sangama", "2. Saluva", "3. Tuluva", "4. Aravidu"], "list_1_hi": ["1. संगम", "2. सालुव", "3. तुलुव", "4. अरविडु"], "list_2": ["Devaraya II", "Saluva Narasimha", "Krishnadevaraya", "Harihara I"], "list_2_hi": ["देवराय द्वितीय", "सालुव नरसिंह", "कृष्णदेवराय", "हरिहर प्रथम"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'The first three pairs are correct. Vijayanagara was ruled by four dynasties in turn: the Sangamas (from 1336), whose founders were Harihara I and Bukka and whose Devaraya II strengthened the cavalry and employed Muslim archers; the Saluvas, founded when the general Saluva Narasimha took the throne around 1485; the Tuluvas, whose Krishnadevaraya marks the empire''s peak; and the Aravidus, who ruled from Penukonda and Chandragiri after the defeat at Talikota in 1565. The fourth pair is wrong: Harihara I was the first Sangama ruler, not an Aravidu.','पहले तीन युग्म सही हैं। विजयनगर पर बारी-बारी से चार राजवंशों ने शासन किया: संगम (1336 से), जिनके संस्थापक हरिहर प्रथम और बुक्क थे और जिनके देवराय द्वितीय ने घुड़सेना को सुदृढ़ किया तथा मुस्लिम धनुर्धर रखे; सालुव, जिसकी स्थापना तब हुई जब सेनापति सालुव नरसिंह ने लगभग 1485 में सिंहासन लिया; तुलुव, जिनके कृष्णदेवराय साम्राज्य के शिखर के प्रतीक हैं; और अरविडु, जिन्होंने 1565 में तालीकोटा की हार के बाद पेनुकोंडा और चंद्रगिरि से शासन किया। चौथा युग्म ग़लत है: हरिहर प्रथम पहले संगम शासक थे, अरविडु नहीं।','l3-t3-his-vijayanagara-dynasties','original_pattern_matched','NCERT Class XII, Themes in Indian History II; NCERT Class VII, Our Pasts II.','draft'),
('upsc','History','Music & Dance','match_the_following','hard','Consider the following pairs of musicians and the instruments they are known for:','संगीतकारों और उन वाद्यों के निम्नलिखित युग्मों पर विचार कीजिए जिनके लिए वे जाने जाते हैं:','{"list_1": ["1. Annapurna Devi", "2. Asad Ali Khan", "3. U. Srinivas", "4. Lalgudi Jayaraman"], "list_1_hi": ["1. अन्नपूर्णा देवी", "2. असद अली ख़ान", "3. यू. श्रीनिवास", "4. लालगुडी जयरामन"], "list_2": ["Surbahar", "Rudra veena", "Mandolin", "Violin"], "list_2_hi": ["सुरबहार", "रुद्र वीणा", "मैंडोलिन", "वायलिन"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correct. Annapurna Devi, daughter of Allauddin Khan of the Maihar gharana, was a celebrated and reclusive player of the surbahar, a bass sitar suited to slow, deep alap; Asad Ali Khan was among the last masters of the rudra veena, the ancient instrument of the dhrupad tradition. U. Srinivas adapted the mandolin, a Western instrument, to the gamakas of Carnatic music; and Lalgudi Jayaraman developed a distinctive style of Carnatic violin, an instrument that entered the Carnatic concert in the nineteenth century and is now its main accompanist.','चारों युग्म सही हैं। मैहर घराने के अलाउद्दीन ख़ान की पुत्री अन्नपूर्णा देवी सुरबहार की प्रसिद्ध और एकांतप्रिय वादक थीं, जो धीमे, गहरे आलाप के अनुकूल बास सितार है; असद अली ख़ान ध्रुपद परंपरा के प्राचीन वाद्य रुद्र वीणा के अंतिम उस्तादों में थे। यू. श्रीनिवास ने पश्चिमी वाद्य मैंडोलिन को कर्नाटक संगीत के गमकों के अनुकूल बनाया; और लालगुडी जयरामन ने कर्नाटक वायलिन की एक विशिष्ट शैली विकसित की, वह वाद्य जो उन्नीसवीं शताब्दी में कर्नाटक संगीत-सभा में आया और अब उसका मुख्य संगत वाद्य है।','l3-t3-his-musicians-surbahar-veena-mandolin-violin','original_pattern_matched','NCERT Class XI, An Introduction to Indian Art; Sangeet Natak Akademi.','draft')
